package br.com.admeclesial.application.matrimonio; import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService; import org.springframework.beans.factory.annotation.Autowired; import br.com.admeclesial.domain.matrimonio.*; import br.com.admeclesial.domain.organizacao.OrganizacaoEclesial; import br.com.admeclesial.infrastructure.persistence.matrimonio.*; import br.com.admeclesial.infrastructure.persistence.organizacao.OrganizacaoEclesialRepository; import br.com.admeclesial.infrastructure.persistence.pessoa.PessoaRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.util.StringUtils; import java.util.*; @Service public class CelebracaoMatrimonialApplicationService { @Autowired SegurancaOrganizacaoService seguranca; final CelebracaoMatrimonialRepository repo; final ProcessoMatrimonialRepository proc; final OrganizacaoEclesialRepository orgRepo; final PessoaRepository pessoas; public CelebracaoMatrimonialApplicationService(CelebracaoMatrimonialRepository r,ProcessoMatrimonialRepository p,OrganizacaoEclesialRepository o,PessoaRepository pe){repo=r;proc=p;orgRepo=o;pessoas=pe;} @Transactional public CelebracaoMatrimonialResponse salvar(CelebracaoMatrimonialRequest r){ProcessoMatrimonial p=proc.findByUuid(r.processoUuid()).orElseThrow(()->new IllegalArgumentException("Processo matrimonial não encontrado."));validar(p.getOrganizacao().getUuid());validar(r.organizacaoEclesialUuid()); if(p.getStatus()==StatusProcessoMatrimonial.CANCELADO)throw new IllegalArgumentException("Processo cancelado não pode ter celebração."); OrganizacaoEclesial o=orgRepo.findByUuid(r.organizacaoEclesialUuid()).orElseThrow(()->new IllegalArgumentException("Organização não encontrada.")); var c=pessoas.findByUuid(r.celebranteUuid()).orElseThrow(()->new IllegalArgumentException("Celebrante não encontrado.")); if(!o.isAtivo()||!c.isAtivo())throw new IllegalArgumentException("Organização e celebrante devem estar ativos."); if(!mesmaEntidade(o,p.getOrganizacao()))throw new IllegalArgumentException("A organização da celebração deve ser a mesma organização do processo matrimonial."); if(r.dataCelebracao().isBefore(p.getDataAbertura()))throw new IllegalArgumentException("Celebração não pode ocorrer antes da abertura do processo."); CelebracaoMatrimonial e=repo.findByProcessoId(p.getId()).orElseGet(CelebracaoMatrimonial::new); e.setProcesso(p);e.setOrganizacao(o);e.setCelebrante(c);e.setDataCelebracao(r.dataCelebracao());e.setLocal(StringUtils.hasText(r.local())?r.local().trim():null);e.setObservacao(StringUtils.hasText(r.observacao())?r.observacao().trim():null); return out(repo.save(e));} @Transactional(readOnly=true) public CelebracaoMatrimonialResponse buscar(UUID u){var e=repo.findByUuid(u).orElseThrow(()->new IllegalArgumentException("Celebração não encontrada."));validar(e.getOrganizacao().getUuid());return out(e);} @Transactional(readOnly=true) public CelebracaoMatrimonialResponse porProcesso(UUID u){var p=proc.findByUuid(u).orElseThrow(()->new IllegalArgumentException("Processo matrimonial não encontrado."));validar(p.getOrganizacao().getUuid());return repo.findByProcessoId(p.getId()).map(this::out).orElseThrow(()->new IllegalArgumentException("Celebração não encontrada."));} private boolean mesmaEntidade(OrganizacaoEclesial a, OrganizacaoEclesial b){return a==b || (a.getId()!=null && b.getId()!=null && a.getId().equals(b.getId()));} private CelebracaoMatrimonialResponse out(CelebracaoMatrimonial e){return new CelebracaoMatrimonialResponse(e.getUuid(),e.getProcesso().getUuid(),e.getOrganizacao().getUuid(),e.getOrganizacao().getNome(),e.getCelebrante().getUuid(),e.getCelebrante().getNome(),e.getDataCelebracao(),e.getLocal(),e.getObservacao());} private void validar(UUID u){if(seguranca!=null)seguranca.validarAcesso(u);}}